import numpy as np

M = 2013

def check_permutation(a3, a1):
    """Checks if P(x) = a3*x^3 + a1*x is a permutation polynomial mod M."""

    def P(x):
        return (a3 * (x**3) + a1 * x) % M

    values = {}
    for x in range(M):
        y = P(x)
        if y in values:
            # Collision found
            return False, x, values[y]
        values[y] = x
    return True, None, None

# Test cases
tests = [
    (2, 1),  # a3=2, a1=1
    (3, 1),  # a3=3, a1=1
    (5, 1)   # a3=5, a1=1
]

results = {}
for a3, a1 in tests:
    is_perm, x1, x2 = check_permutation(a3, a1)
    results[(a3, a1)] = (is_perm, x1, x2)
    if not is_perm:
        print(f"--- Test Failed for a3={a3}, a1={a1} ---")
        print(f"Collision found: P({x1}) = P({x2}) = {P(x1)} mod {M}")
    else:
        print(f"--- Test Passed for a3={a3}, a1={a1} ---")

print("\nSummary:", results)

